import {validWorkbookReport,workbookChoices,workbookQuestions,questionnaireLocale} from './innerly-v1-model.mjs';
import {consolidatedComparisonMarkup} from './report-comparison-summary.mjs';
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const date=r=>new Date(r.createdAt).toLocaleString(undefined,{day:'numeric',month:'short',year:'numeric',hour:'2-digit',minute:'2-digit'});
export function comparisonData(reports,{language,fromId,toId,question=0}={}){
 const valid=[...new Map(reports.filter(validWorkbookReport).map(r=>[r.id,r])).values()],counts=new Map();for(const r of valid)counts.set(r.language,(counts.get(r.language)||0)+1);const code=language||valid.find(r=>counts.get(r.language)>1)?.language||valid[0]?.language||'en';
 const rows=[...new Map(valid.filter(r=>r.language===code).map(r=>[r.id,r])).values()].sort((a,b)=>Date.parse(a.createdAt)-Date.parse(b.createdAt)||a.id.localeCompare(b.id));
 let to=rows.find(r=>r.id===toId)||rows.at(-1),from=rows.find(r=>r.id===fromId)||rows[0];
 if(from&&to&&rows.indexOf(from)>rows.indexOf(to))[from,to]=[to,from];
 const index=Number.isInteger(question)&&question>=0&&question<36?question:0;
 return {rows,language:code,from,to,question:index,changed:from&&to?from.answers.filter((v,i)=>v!==to.answers[i]).length:0};
}
export function comparisonMarkup(reports,selection={}){
 const data=comparisonData(reports,selection),{rows,from,to,question,language,changed}=data;
 if(!rows.length)return '';
 const languages=[...new Set(reports.filter(validWorkbookReport).map(r=>r.language))];
 if(rows.length<2)return `<section class="report-comparison comparison-invitation" aria-labelledby="comparison-invitation-title"><span class="comparison-seed" aria-hidden="true">🌱</span><p class="mh-kicker">YOUR NEXT CHAPTER</p><h2 id="comparison-invitation-title">One check-in. A starting point for you.</h2><p>Your first check-in is saved. Come back for another when it feels right, and see what has changed in your thoughts, feelings and everyday patterns.</p><div class="comparison-invitation-steps"><span>✓ Your starting point</span><span>○ Your next check-in</span><span>○ Your comparison</span></div><p class="comparison-invitation-note">Your comparison will appear after two saved check-ins in the same question language. There’s no rush—choose a pace that works for you.</p>${languages.length>1?`<label>Question language<select data-compare="language">${languages.map(l=>`<option value="${l}" ${l===language?'selected':''}>${new Intl.DisplayNames(['en'],{type:'language'}).of(l)}</option>`).join('')}</select></label>`:''}<button class="mh-primary" data-action="new-test">Start a new check-in →</button></section>`;
 const options=selected=>rows.map((r,i)=>`<option value="${esc(r.id)}" ${r.id===selected?.id?'selected':''}>${esc(date(r))} · Check-in ${i+1}</option>`).join('');
 const labels=workbookChoices(language),first=Date.parse(rows[0].createdAt),span=Date.parse(rows.at(-1).createdAt)-first;
 const x=r=>span?172+((Date.parse(r.createdAt)-first)/span)*500:422,y=v=>238-v*48;
 const segments=rows.slice(1).map((r,i)=>Number.isInteger(r.answers[question])&&Number.isInteger(rows[i].answers[question])?`<line x1="${x(rows[i])}" y1="${y(rows[i].answers[question])}" x2="${x(r)}" y2="${y(r.answers[question])}"/>`:'').join('');
 const points=rows.filter(r=>Number.isInteger(r.answers[question])).map(r=>`<circle cx="${x(r)}" cy="${y(r.answers[question])}" r="6"><title>${esc(date(r)+': '+labels[r.answers[question]])}</title></circle>`).join('');
 return `<section class="report-comparison" aria-labelledby="comparison-title"><p class="mh-kicker">YOUR RESPONSES OVER TIME</p><h2 id="comparison-title">Notice what has changed.</h2><p>Compare check-ins from the same questionnaire and language. Each point is an actual saved response; days without a check-in have no measurement.</p><div class="comparison-selectors">${languages.length>1?`<label>Question language<select data-compare="language">${languages.map(l=>`<option value="${l}" ${l===language?'selected':''}>${new Intl.DisplayNames(['en'],{type:'language'}).of(l)}</option>`).join('')}</select></label>`:''}<label>Before<select data-compare="fromId">${options(from)}</select></label><label>After<select data-compare="toId">${options(to)}</select></label></div>${rows.length<2?'<p class="history-notice">Save another check-in to see a before-and-after comparison.</p>':`<div class="comparison-summary"><strong>${changed} of 36</strong><span>answers differ between these two reports</span></div>`}<label class="comparison-question">Choose a question to follow<select data-compare="question">${questionnaireLocale(language).dimensions.map((name,d)=>`<optgroup label="${esc(name)}">${workbookQuestions.slice(d*6,d*6+6).map((q,j)=>`<option value="${d*6+j}" ${d*6+j===question?'selected':''}>${d*6+j+1}. ${esc(q.texts[language]||q.texts.en)}</option>`).join('')}</optgroup>`).join('')}</select></label><h3>${esc(workbookQuestions[question].texts[language]||workbookQuestions[question].texts.en)}</h3><div class="comparison-chart" role="region" tabindex="0" aria-label="Response timeline"><svg viewBox="0 0 720 290" role="img" aria-label="Your response frequency over time. Exact answers follow below.">${labels.map((label,i)=>`<text x="158" y="${y(i)+5}" text-anchor="end">${esc(label)}</text><line class="comparison-grid" x1="172" x2="672" y1="${y(i)}" y2="${y(i)}"/>`).join('')}<g class="comparison-line">${segments}</g><g class="comparison-points">${points}</g><text x="172" y="278">${esc(new Date(rows[0].createdAt).toLocaleDateString())}</text>${rows.length>1?`<text x="672" y="278" text-anchor="end">${esc(new Date(rows.at(-1).createdAt).toLocaleDateString())}</text>`:''}</svg></div><p class="history-notice">Higher means a more frequent response, not automatically better health. A helpful habit and a difficulty can move in opposite directions. These are reflection responses, not a clinical progress score.</p><details><summary>Exact dates and responses (${rows.length})</summary><div class="comparison-table"><table><thead><tr><th>Check-in</th><th>Response</th></tr></thead><tbody>${rows.map(r=>`<tr><td>${esc(date(r))}</td><td>${esc(labels[r.answers[question]]||'Not answered')}</td></tr>`).join('')}</tbody></table></div></details>${rows.length>1?`<details><summary>Compare all 36 answers</summary><div class="comparison-table"><table><thead><tr><th>Question</th><th>Before · ${esc(date(from))}</th><th>After · ${esc(date(to))}</th></tr></thead><tbody>${workbookQuestions.map((q,i)=>`<tr class="${from.answers[i]===to.answers[i]?'':'response-changed'}"><th scope="row">${i+1}. ${esc(q.texts[language]||q.texts.en)}</th><td>${esc(labels[from.answers[i]]||'Not answered')}</td><td>${esc(labels[to.answers[i]]||'Not answered')}</td></tr>`).join('')}</tbody></table></div></details>`:''}${rows.length>1?consolidatedComparisonMarkup(from,to):''}</section>`;
}
export function accountHistoryMarkup({localReports=[],cloud,config,selection={},saving=false,status=''}){
 const reports=cloud.userId?cloud.reports:[],earlier=localReports.filter(r=>!reports.some(c=>c.clientId===r.id||c.id===r.id));
 const rows=(items,account)=>items.map(r=>`<article><div class="mh-saved-copy"><span>${esc(date(r))}</span><strong>${r.version==='innerly-workbook-v1'?'36-question check-in':'Earlier check-in'}</strong><small>${esc(new Intl.DisplayNames(['en'],{type:'language'}).of(r.language))}${account?' · Saved to your account':''}</small></div><div class="mh-saved-actions"><button class="mh-saved-open" ${account?'data-cloud-open':'data-open'}="${esc(r.id)}">View report</button>${!account&&r.version==='innerly-workbook-v1'?`<button data-cloud-save="${esc(r.id)}" ${saving?'disabled':''}>${saving?'Saving…':cloud.userId?'Save to account':'Sign in to save'}</button>`:''}<button class="report-delete-button" ${account?'data-cloud-delete':'data-delete'}="${esc(r.id)}">Delete</button></div></article>`).join('');
 if(!cloud.userId)return `<section class="mh-history history-welcome"><div class="history-welcome-hero"><div class="history-welcome-copy"><p class="mh-kicker">YOUR PERSONAL SPACE</p><h1>Your reflections,<br><span>all in one place.</span></h1><p class="history-welcome-intro">Every check-in is a moment to understand yourself. Sign in to revisit your reports and notice what changes over time.</p><button class="history-signin" data-cloud-action="signin">Sign in to my reports <span aria-hidden="true">→</span></button><p class="history-login-methods">Continue with Google or email</p><button class="history-guest-start" data-action="new-test">New here? Start a check-in <span aria-hidden="true">↗</span></button></div><div class="history-welcome-art" aria-hidden="true"><div class="history-art-orbit"></div><div class="history-art-paper history-art-back"></div><div class="history-art-paper history-art-front"><span class="history-art-eyebrow">A MOMENT FOR YOUR MIND</span><span class="history-art-title">Your reflection</span><div class="history-art-symbol"><svg viewBox="0 0 120 100" fill="none"><path d="M60 85V45M60 65C34 65 23 49 23 30c24 0 37 13 37 35ZM60 49C60 24 77 13 98 13c0 23-14 36-38 36Z" stroke="currentColor" stroke-width="3" stroke-linecap="round" stroke-linejoin="round"/><path d="M32 87h56" stroke="currentColor" stroke-width="3" stroke-linecap="round"/></svg></div><div class="history-art-lines"><i></i><i></i><i></i></div><span class="history-art-caption">A little closer to yourself.</span></div><div class="history-art-note"><span>✦</span> Your story, one check-in at a time.</div></div></div><div class="history-welcome-benefits"><article><span aria-hidden="true">01</span><div><h2>Keep your moments</h2><p>Your completed reports, saved by date.</p></div></article><article><span aria-hidden="true">02</span><div><h2>Notice your patterns</h2><p>Compare two check-ins and explore what’s changed.</p></div></article><article><span aria-hidden="true">03</span><div><h2>Pick up where you left off</h2><p>Continue your check-in on any device after signing in.</p></div></article></div>${earlier.length?`<details class="history-earlier history-welcome-earlier"><summary>Looking for an earlier report? <span>${earlier.length} available</span></summary><p>These reports aren’t in your account yet. You can still open them here and choose which ones to save after signing in.</p><div class="mh-saved-list">${rows(earlier,false)}</div></details>`:''}</section>`;
 return `<section class="mh-history"><p class="mh-kicker">MY REPORTS</p><h1>Your check-ins. Your pace.</h1>${!cloud.userId?'<div class="history-notice"><p>Sign in to keep your reports together and pick up where you left off, on any device.</p><button class="mh-primary" data-cloud-action="signin">Sign in</button></div>':`<div class="history-toolbar"><p>Your check-ins save automatically to your account.</p><button class="mh-secondary" data-cloud-action="refresh" ${cloud.loading?'disabled':''}>Refresh reports</button></div>${config&&!config.cloudEnabled?'<p class="history-notice">Account saving is temporarily unavailable. Please keep this page open and try again.</p>':''}`}${status?`<p class="history-notice" role="status">${esc(status)}</p>`:''}${cloud.error&&cloud.userId?`<p class="history-notice" role="alert">${esc(cloud.error)} <button data-cloud-action="refresh">Try again</button></p>`:''}${cloud.loading?'<p role="status">Loading your reports…</p>':''}${reports.length?`<div class="mh-saved-list">${rows(reports,true)}</div>`:cloud.userId&&!cloud.loading?'<p class="mh-empty">Your completed reports will appear here automatically.</p>':''}${cloud.userId&&cloud.cursor?'<button class="mh-secondary" data-cloud-action="more">Load older reports</button>':''}${comparisonMarkup(reports,selection)}${earlier.length?`<details class="history-earlier"><summary>Earlier reports (${earlier.length})</summary><p>These reports aren’t saved to your account yet. Review them and save the ones that belong to you.</p><div class="mh-saved-list">${rows(earlier,false)}</div></details>`:''}<button class="mh-primary" data-action="new-test">Start a new test →</button></section>`;
}
